namespace App.Common;

/// <summary>A field of an update: absent (it keeps its value), or present with a value, which may be null.</summary>
public sealed class Patch<T>
{
    private Patch(bool isPresent, T? value)
    {
        IsPresent = isPresent;
        Value = value;
    }

    /// <summary>The field keeps its value.</summary>
    public static Patch<T> Absent { get; } = new(false, default);

    /// <summary>The field takes this value, which may be null.</summary>
    public static Patch<T> Of(T? value) => new(true, value);

    public bool IsPresent { get; }

    /// <summary>The value to set; default when absent.</summary>
    public T? Value { get; }

    public override string ToString() => IsPresent ? $"Patch[{Value}]" : "Patch.Absent";
}

using System.Globalization;
using App.ApplicationModels;
using App.Dtos;

namespace App.Conversions;

/// <summary>Conversions between the application models and the "customers" table: what the service takes and returns.</summary>
public static class CustomerConversions
{
    /// <summary>A CustomerForm as the customers table takes it.</summary>
    public static CustomerCreate CustomerFormToCustomerCreate(CustomerForm model)
    {
        return new CustomerCreate
        {
            Email = model.Email,
            FullName = string.Join(" ", model.FirstName, model.LastName),
            Status = Pair(new Dictionary<string, string> { ["ACTIVE"] = "active", ["BLOCKED"] = "blocked" }, model.Status switch { CustomerState.ACTIVE => "ACTIVE", CustomerState.BLOCKED => "BLOCKED", _ => throw new ArgumentOutOfRangeException(nameof(CustomerState)) }, null),
            CreatedAt = DateTimeOffset.FromUnixTimeSeconds(model.SignedUp).UtcDateTime,
            BalanceCents = (int)Math.Round(((double)model.Balance * 100)),
            Nickname = default!, // TODO: Nickname: the matching waits for review (nickname)
            Country = default!, // TODO: Country: no field of the model gives it
        };
    }

    /// <summary>A row of the customers table as a CustomerForm.</summary>
    public static CustomerForm CustomerReadToCustomerForm(CustomerRead row)
    {
        return new CustomerForm
        {
            Email = row.Email,
            FirstName = default!, // TODO: FirstName: Mapper's relation only goes the other way (firstName, lastName)
            LastName = default!, // TODO: LastName: Mapper's relation only goes the other way (firstName, lastName)
            Status = Pair(new Dictionary<string, string> { ["active"] = "ACTIVE", ["blocked"] = "BLOCKED" }, row.Status, null) switch { "ACTIVE" => CustomerState.ACTIVE, "BLOCKED" => CustomerState.BLOCKED, _ => throw new ArgumentException("No CustomerState for this value") },
            SignedUp = (new DateTimeOffset(DateTime.SpecifyKind(row.CreatedAt, DateTimeKind.Utc))).ToUnixTimeSeconds(),
            Balance = (decimal)((double)row.BalanceCents / 100),
            Nickname = default!, // TODO: Nickname: the matching waits for review (nickname)
        };
    }

    /// <summary>A value as the text Mapper compares.</summary>
    private static string Text(object? value) => Convert.ToString(value, CultureInfo.InvariantCulture) ?? "";

    /// <summary>The value an enum pair gives, or the fallback; a value without a pair is an error.</summary>
    private static string Pair(Dictionary<string, string> pairs, object? value, string? fallback) =>
        pairs.TryGetValue(Text(value), out var found) ? found : fallback ?? throw new ArgumentException($"No pair for {value}");
}

