namespace App.Services;

/// <summary>Operations on customers. Each write runs in its own transaction.</summary>
public class CustomerService(IUnitOfWork unitOfWork)
{
    private readonly IUnitOfWork uow = unitOfWork;

    /// <summary>Checks the values against the rules of the "customers" table, and the rows they point to; throws ValidationFailedException with every problem.</summary>
    private static async Task ValidateAsync(IUnitOfWork uow, Dictionary<string, object?> values, Customer? current)
    {
        var creating = current is null;
        var errors = new List<FieldError>();
        {
            var value = values.GetValueOrDefault("Email");
            if (value is null)
            {
                if (creating || values.ContainsKey("Email")) errors.Add(new FieldError("email", "is required"));
            }
            else
            {
                if (value is string text && text.Length > 120) errors.Add(new FieldError("email", "is longer than 120 characters"));
            }
        }
        {
            var value = values.GetValueOrDefault("FullName");
            if (value is null)
            {
                if (creating || values.ContainsKey("FullName")) errors.Add(new FieldError("full_name", "is required"));
            }
            else
            {
                if (value is string text && text.Length > 120) errors.Add(new FieldError("full_name", "is longer than 120 characters"));
            }
        }
        {
            var value = values.GetValueOrDefault("Status");
            if (value is null)
            {
                if (creating || values.ContainsKey("Status")) errors.Add(new FieldError("status", "is required"));
            }
            else
            {
                if (value is string text && text.Length > 10) errors.Add(new FieldError("status", "is longer than 10 characters"));
                if (!new[] { "active", "blocked" }.Contains(Convert.ToString(value, CultureInfo.InvariantCulture))) errors.Add(new FieldError("status", "must be one of: active, blocked"));
            }
        }
        {
            var value = values.GetValueOrDefault("CreatedAt");
            if (value is null)
                if (creating || values.ContainsKey("CreatedAt")) errors.Add(new FieldError("created_at", "is required"));
        }
        {
            var value = values.GetValueOrDefault("BalanceCents");
            if (value is null)
                if (creating || values.ContainsKey("BalanceCents")) errors.Add(new FieldError("balance_cents", "is required"));
        }
        {
            var value = values.GetValueOrDefault("Nickname");
            if (value is not null)
            {
                if (value is string text && text.Length > 40) errors.Add(new FieldError("nickname", "is longer than 40 characters"));
            }
        }
        {
            var value = values.GetValueOrDefault("Country");
            if (value is null)
            {
                if (creating || values.ContainsKey("Country")) errors.Add(new FieldError("country", "is required"));
            }
            else
            {
                if (value is string text && text.Length > 2) errors.Add(new FieldError("country", "is longer than 2 characters"));
            }
        }
        if (errors.Count > 0) throw new ValidationFailedException("Customer", errors);
    }

    /// <summary>Values that must be unique are not taken by another row.</summary>
    private static async Task CheckUniqueAsync(IUnitOfWork uow, Dictionary<string, object?> values, Customer? current)
    {
        {
            var email = values.TryGetValue("Email", out var givenEmail) ? (string?)givenEmail : current?.Email;
            if (email is not null)
            {
                var other = await uow.Customers.FindByEmailAsync(email);
                if (other is not null && (current is null || !Equals(other.Id, current.Id)))
                    throw new ConflictException("Customer", "email is already taken", ["Email"]);
            }
        }
    }

    /// <summary>Every check before a write: the values, the rows they point to, the unique values.</summary>
    private static async Task CheckAsync(IUnitOfWork uow, Dictionary<string, object?> values, Customer? current)
    {
        await ValidateAsync(uow, values, current);
        await CheckUniqueAsync(uow, values, current);
    }

    /// <summary>Sets the given values on the entity.</summary>
    private static void Apply(Customer entity, Dictionary<string, object?> values)
    {
        if (values.TryGetValue("Email", out var email)) entity.Email = (string)email!;
        if (values.TryGetValue("FullName", out var fullName)) entity.FullName = (string)fullName!;
        if (values.TryGetValue("Status", out var status)) entity.Status = (string)status!;
        if (values.TryGetValue("CreatedAt", out var createdAt)) entity.CreatedAt = (DateTime)createdAt!;
        if (values.TryGetValue("BalanceCents", out var balanceCents)) entity.BalanceCents = (int)balanceCents!;
        if (values.TryGetValue("Nickname", out var nickname)) entity.Nickname = (string?)nickname;
        if (values.TryGetValue("Country", out var country)) entity.Country = (string)country!;
    }

    /// <summary>The Customer with this key; NotFoundException when there is none.</summary>
    private static async Task<Customer> FindAsync(IUnitOfWork uow, int id) =>
        await uow.Customers.FindByIdAsync(id) ?? throw new NotFoundException("Customer", id);

    /// <summary>The Customer as services return it.</summary>
    private static CustomerRead Read(Customer entity) => new() { Id = entity.Id, Email = entity.Email, FullName = entity.FullName, Status = entity.Status, CreatedAt = entity.CreatedAt, BalanceCents = entity.BalanceCents, Nickname = entity.Nickname, Country = entity.Country };

    /// <summary>The values an update gives, by field.</summary>
    private static Dictionary<string, object?> Given(CustomerUpdate changes)
    {
        var values = new Dictionary<string, object?>();
        if (changes.Email is { IsPresent: true } email) values["Email"] = email.Value;
        if (changes.FullName is { IsPresent: true } fullName) values["FullName"] = fullName.Value;
        if (changes.Status is { IsPresent: true } status) values["Status"] = status.Value;
        if (changes.CreatedAt is { IsPresent: true } createdAt) values["CreatedAt"] = createdAt.Value;
        if (changes.BalanceCents is { IsPresent: true } balanceCents) values["BalanceCents"] = balanceCents.Value;
        if (changes.Nickname is { IsPresent: true } nickname) values["Nickname"] = nickname.Value;
        if (changes.Country is { IsPresent: true } country) values["Country"] = country.Value;
        return values;
    }

    /// <summary>Stores a new Customer after checking it.</summary>
    public async Task<CustomerRead> CreateCustomerAsync(CustomerCreate data)
    {
        var values = new Dictionary<string, object?>();
        if (data.Email is not null) values["Email"] = data.Email;
        if (data.FullName is not null) values["FullName"] = data.FullName;
        if (data.Status is not null) values["Status"] = data.Status;
        values["CreatedAt"] = data.CreatedAt;
        values["BalanceCents"] = data.BalanceCents;
        if (data.Nickname is not null) values["Nickname"] = data.Nickname;
        if (data.Country is not null) values["Country"] = data.Country;
        return await this.uow.TransactionAsync(async uow =>
        {
            await CheckAsync(uow, values, null);
            var entity = new Customer();
            Apply(entity, values);
            return Read(await uow.Customers.InsertAsync(entity));
        });
    }

    /// <summary>The Customer with this key; NotFoundException when there is none.</summary>
    public async Task<CustomerRead> GetCustomerAsync(int id) => Read(await FindAsync(uow, id));

    /// <summary>A page of customers, by primary key.</summary>
    public async Task<Page<CustomerRead>> ListCustomersAsync(int offset, int limit) => (await uow.Customers.ListAsync(offset, limit)).Map(Read);

    /// <summary>Changes the given values of a Customer.</summary>
    public async Task<CustomerRead> UpdateCustomerAsync(int id, CustomerUpdate changes)
    {
        var values = Given(changes);
        return await this.uow.TransactionAsync(async uow =>
        {
            var current = await FindAsync(uow, id);
            await CheckAsync(uow, values, current);
            Apply(current, values);
            return Read(await uow.Customers.UpdateAsync(current));
        });
    }

    /// <summary>Deletes a Customer.</summary>
    public async Task DeleteCustomerAsync(int id)
    {
        await this.uow.TransactionAsync(async uow =>
        {
            var current = await FindAsync(uow, id);
            await uow.Customers.DeleteAsync(current);
        });
    }

    /// <summary>The Customer with this email, or null.</summary>
    public async Task<CustomerRead?> FindCustomerByEmailAsync(string email) => await uow.Customers.FindByEmailAsync(email) is { } entity ? Read(entity) : null;
}

